calcularGananciaExentaInmuebleUrbanoAdquirido2012 = ({
  ganancia,
  gananciaTotal,
  gananciaExentaPrevia,
}: {
  readonly ganancia: GananciaPatrimonialTransmision
  readonly gananciaTotal: Decimal
  readonly gananciaExentaPrevia: Decimal
}): Decimal =>
  Match.value(ganancia.exencionInmuebleUrbanoAdquirido2012).pipe(
    Match.withReturnType<Decimal>(),
    Match.when(Match.undefined, () => IMPORTE_CERO),
    Match.orElse((exencion) => {
      const parametro =
        EXENCION_50_POR_CIENTO_GANANCIAS_INMUEBLES_URBANOS_ADQUIRIDOS_2012
      const cumpleRangoFecha =
        exencion.fechaAdquisicion >= parametro.fechaInicioAdquisicion &&
        exencion.fechaAdquisicion <= parametro.fechaFinAdquisicion

      return Match.value({
        inmuebleUrbano: exencion.inmuebleUrbano,
        tituloOneroso: exencion.tituloOneroso,
        vinculada: exencion.operacionConPersonaOEntidadVinculada === true,
        cumpleRangoFecha,
      }).pipe(
        Match.withReturnType<Decimal>(),
        Match.when(
          {
            inmuebleUrbano: true,
            tituloOneroso: true,
            vinculada: false,
            cumpleRangoFecha: true,
          },
          () =>
            Decimal.max(0, gananciaTotal.minus(gananciaExentaPrevia)).mul(
              parametro.porcentajeExento
            )
        ),
        Match.orElse(() => IMPORTE_CERO)
      )
    })
  )

calcularGananciaExentaMayores65 = ({
  anio,
  edadContribuyente,
  gananciaTotal,
  tratamiento,
  convertirCentimos,
}: {
  readonly anio: AnioFiscal
  readonly edadContribuyente: number
  readonly gananciaTotal: Decimal
  readonly tratamiento: TratamientoGananciaPatrimonialMayores65
  readonly convertirCentimos: typeof centimosAEuros
}): Decimal =>
  Match.value(edadContribuyente).pipe(
    Match.when(
      (edadContribuyente) => edadContribuyente < 65,
      () => IMPORTE_CERO
    ),
    Match.orElse(() =>
      Match.valueTags(tratamiento, {
        SinExencionMayores65: () => IMPORTE_CERO,
        ViviendaHabitualMayores65: () => gananciaTotal,
        ReinversionRentaVitaliciaMayores65: ({
          importeReinvertidoRentaVitaliciaCentimos,
          importeTransmisionCentimos,
          reinversionesPreviasRentaVitaliciaCentimos,
        }) =>
          anio < 2015
            ? IMPORTE_CERO
            : calcularExencionPorReinversionEnRentaVitalicia({
                gananciaTotal,
                importeTransmision: convertirCentimos(
                  importeTransmisionCentimos
                ),
                importeReinvertido: convertirCentimos(
                  importeReinvertidoRentaVitaliciaCentimos
                ),
                reinversionesPrevias: convertirCentimos(
                  reinversionesPreviasRentaVitaliciaCentimos
                ),
              }),
      })
    )
  )

calcularExencionPorReinversionEnRentaVitalicia = ({
  gananciaTotal,
  importeReinvertido,
  importeTransmision,
  reinversionesPrevias,
}: {
  readonly gananciaTotal: Decimal
  readonly importeTransmision: Decimal
  readonly importeReinvertido: Decimal
  readonly reinversionesPrevias: Decimal
}): Decimal =>
  Match.value(importeTransmision).pipe(
    Match.when(
      (importeTransmision) => importeTransmision.lte(0),
      () => IMPORTE_CERO
    ),
    Match.orElse((importeTransmision) => {
      const margenReinversion = Decimal.max(
        0,
        LIMITE_REINVERSION_RENTA_VITALICIA_MAYORES_65.minus(
          reinversionesPrevias
        )
      )
      const reinversionComputable = Decimal.min(
        importeReinvertido,
        margenReinversion
      )
      const proporcionExenta = Decimal.min(
        1,
        reinversionComputable.div(importeTransmision)
      )

      return gananciaTotal.mul(proporcionExenta)
    })
  )

export function calcularGastosTrabajo(caso: GastosTrabajo): ResultadoGastos {
  const decoded = Schema.decodeUnknownResult(GastosTrabajo)(caso, {
    onExcessProperty: "error",
  })
  if (Result.isFailure(decoded))
    return rechazo("Entrada inválida, incompleta o con campos ajenos")
  const c = decoded.success
  if (c.territorio !== "comun" || c.ejercicio === 2026)
    return rechazo("Ámbito territorial o vigencia 2026 no cerrados")
  if (c.movilidad !== "ninguna")
    return rechazo(
      "Movilidad ordinaria/histórica y DT6 requieren contrato temporal y de rendimientos asociados; no acumulables"
    )
  if (c.discapacidadActiva === "pendiente")
    return rechazo("Discapacidad activa desconocida")
  if (
    c.discapacidadActiva !== "ninguna" &&
    (c.ejercicio < 2015 ||
      c.rendimientos.length !== 1 ||
      c.rendimientos.some(
        (r) => r.clase !== "empleo-laboral" && r.clase !== "empleo-estatutario"
      ) ||
      c.discapacidadActiva.acreditadaDuranteTodoElTrabajo !== "si" ||
      c.discapacidadActiva.ayudaOMovilidadReducida === "desconocido")
  )
    return rechazo(
      "Discapacidad: solo empleo efectivo único con acreditación durante todos los rendimientos, desde 2015; asociación parcial/histórica pendiente"
    )
  if (c.reduccionesArt18 !== "ninguna")
    return rechazo("Imputación y reducciones art18 pendientes")
  if (new Set(c.rendimientos.map((r) => r.id)).size !== c.rendimientos.length)
    return rechazo("Rendimiento duplicado")
  let bruto = new D(0),
    ordinarios = new D(0),
    colegio = new D(0),
    defensa = new D(0)
  for (const r of c.rendimientos) {
    if (r.clase === "desconocido" || r.cotizaciones.clase !== "efectivas")
      return rechazo("Clase de trabajo o cotizaciones efectivas no acreditadas")
    if (
      [
        r.sindicato.satisfecho,
        r.colegio.satisfecho,
        r.colegio.obligatorio,
        r.colegio.finesEsenciales,
        r.defensa.satisfecho,
        r.defensa.litigioDirectoPagador,
      ].includes("desconocido")
    )
      return rechazo("Requisitos de los gastos desconocidos")
    bruto = bruto.plus(r.integro)
    ordinarios = ordinarios
      .plus(r.cotizaciones.seguridadSocial)
      .plus(r.cotizaciones.derechosPasivos)
      .plus(r.cotizaciones.colegiosHuerfanos)
    if (r.sindicato.satisfecho === "si")
      ordinarios = ordinarios.plus(r.sindicato.importe)
    if (
      r.colegio.satisfecho === "si" &&
      r.colegio.obligatorio === "si" &&
      r.colegio.finesEsenciales === "si"
    )
      colegio = colegio.plus(r.colegio.importe)
    if (
      r.defensa.satisfecho === "si" &&
      r.defensa.litigioDirectoPagador === "si"
    )
      defensa = defensa.plus(r.defensa.importe)
  }
  const gastos = ordinarios.plus(D.min(colegio, 500)).plus(D.min(defensa, 300))
  const previo = bruto.minus(gastos)
  const teoricos = c.ejercicio >= 2015 ? 2000 : 0
  const generales = D.min(teoricos, D.max(0, previo))
  const incremento =
    c.discapacidadActiva === "ninguna"
      ? 0
      : c.discapacidadActiva.grado === "65-o-mas" ||
          c.discapacidadActiva.ayudaOMovilidadReducida === "si"
        ? 7750
        : 3500
  const discapacidad = D.min(incremento, D.max(0, previo.minus(generales)))
  return {
    estado: "calculado",
    discapacidadAplicada: discapacidad.toString(),
    integro: bruto.toString(),
    gastosAE: gastos.toString(),
    generalesTeoricos: String(teoricos),
    generalesAplicados: generales.toString(),
    netoPrevioArt20: previo.toString(),
    netoArt19: previo.minus(generales).minus(discapacidad).toString(),
    fuente: "LIRPF art19; Ley26/2014 pp11–12; RIRPF art10",
    aceptacionFiscal: "pendiente",
  }
}

