export function calcularDeduccionTrabajo(
  caso: DeduccionTrabajo
): ResultadoDeduccion {
  const decoded = Schema.decodeUnknownResult(DeduccionTrabajo)(caso, {
    onExcessProperty: "error",
  })
  if (Result.isFailure(decoded))
    return rechazo("Entrada de deducción inválida o etapa incorrecta")
  const c = decoded.success
  let legal: Decimal, limite: Decimal, fuente: string
  if (c.regla === "art80bis") {
    if (
      new D(c.tipoMedioEstatalPorcentaje).gt(100) ||
      new D(c.tipoMedioAutonomicoPorcentaje).gt(100)
    )
      return rechazo("Tipos medios fuera de rango")
    legal = D.max(
      0,
      new D(400).minus(
        D.max(0, new D(c.baseImponible).minus(8000)).times("0.1")
      )
    )
    limite = new D(c.rendimientoComputableTrabajoActividad)
      .times(
        new D(c.tipoMedioEstatalPorcentaje).plus(
          c.tipoMedioAutonomicoPorcentaje
        )
      )
      .div(100)
    fuente = "LIRPF art80bis histórico; Ley26/2009 art70; arts63.2 y74.2"
  } else {
    if (c.ejercicio !== 2025)
      return rechazo(
        "DA61 2026: vigencia y alcance pendientes de cierre en esta implementación"
      )
    if (c.calificacion !== "laboral-estatutaria-acreditada")
      return rechazo("Servicios efectivos sin calificación acreditada")
    if (new D(c.cuotaTrasArt80).gt(c.cuotaLiquidaTotal))
      return rechazo("Cuota posterior al art80 superior a cuota líquida")
    if (new D(c.netoReducidoServicios).gt(c.brutoServicios))
      return rechazo("Neto atribuible superior a sus servicios íntegros")
    if (new D(c.netoReducidoServicios).gt(c.baseLiquidableGeneral))
      return rechazo("Proporción con pérdidas/compensaciones no cerrada")
    legal =
      new D(c.otrasRentasNoExentas).gt(6500) || new D(c.brutoServicios).eq(0)
        ? new D(0)
        : D.max(
            0,
            new D(340).minus(
              D.max(0, new D(c.brutoServicios).minus(16576)).times("0.2")
            )
          )
    limite = new D(c.baseLiquidableGeneral).eq(0)
      ? new D(0)
      : new D(c.cuotaIntegraGeneral)
          .times(c.netoReducidoServicios)
          .div(c.baseLiquidableGeneral)
    fuente = "Ley5/2025 DF3 pp46–47; AEAT2025 pp1372–1375"
  }
  const aplicable = D.min(legal, limite, c.cuotaTrasArt80)
  return {
    estado: "calculado",
    deduccionLegal: legal.toString(),
    limiteAtribuible: limite.toString(),
    importeAplicable: aplicable.toString(),
    cuotaPosterior: new D(c.cuotaTrasArt80).minus(aplicable).toString(),
    fuente,
    aceptacionFiscal: "pendiente",
  }
}

cuotaSolidaridad = (
  exceso: Decimal,
  baseMaxima: Decimal,
  tipos: readonly [string, string, string]
): Decimal => {
  const primerExceso = Decimal.min(exceso, baseMaxima.mul("0.1"))
  const segundoExceso = Decimal.min(
    Decimal.max(0, exceso.minus(baseMaxima.mul("0.1"))),
    baseMaxima.mul("0.4")
  )
  const excesoRestante = Decimal.max(0, exceso.minus(baseMaxima.mul("0.5")))
  return primerExceso
    .mul(tipos[0])
    .plus(segundoExceso.mul(tipos[1]))
    .plus(excesoRestante.mul(tipos[2]))
}

calcularDesgloseCotizacionesSocialesLegacy = ({
  salarioBrutoAnual,
  anio,
}: EntradaCotizacionesSocialesLegacy): DesgloseCotizacionesSociales => {
  const parametros = obtenerParametrosCotizacionLegacy(anio)
  const baseCotizacion = baseCotizacionPara(salarioBrutoAnual, parametros)
  const cotizacionesOrdinarias = {
    cotizacionEmpresarial: baseCotizacion.baseOrdinaria.mul(
      sumarTipoCotizacionLegacy(parametros, "empresarial")
    ),
    cotizacionTrabajador: baseCotizacion.baseOrdinaria.mul(
      sumarTipoCotizacionLegacy(parametros, "trabajador")
    ),
  }
  const cotizacionesMei = {
    cotizacionEmpresarial: baseCotizacion.baseOrdinaria.mul(
      parametros.mei.empresarial
    ),
    cotizacionTrabajador: baseCotizacion.baseOrdinaria.mul(
      parametros.mei.trabajador
    ),
  }
  const cotizacionesSolidaridad = repartirCotizacionSolidaridad(
    calcularTotalSolidaridad(baseCotizacion, parametros)
  )
  const cotizacionesTotales = sumarCotizacionesSociales(
    sumarCotizacionesSociales(cotizacionesOrdinarias, cotizacionesMei),
    cotizacionesSolidaridad
  )

  return {
    baseOrdinaria: baseCotizacion.baseOrdinaria,
    excesoBase: baseCotizacion.excesoBase,
    cotizacionEmpresarial: cotizacionesTotales.cotizacionEmpresarial,
    cotizacionTrabajador: cotizacionesTotales.cotizacionTrabajador,
    cotizacionEmpresarialOrdinaria:
      cotizacionesOrdinarias.cotizacionEmpresarial,
    cotizacionTrabajadorOrdinaria: cotizacionesOrdinarias.cotizacionTrabajador,
    meiEmpresarial: cotizacionesMei.cotizacionEmpresarial,
    meiTrabajador: cotizacionesMei.cotizacionTrabajador,
    solidaridadEmpresarial: cotizacionesSolidaridad.cotizacionEmpresarial,
    solidaridadTrabajador: cotizacionesSolidaridad.cotizacionTrabajador,
  }
}

