      (anio) => anio >= 2026,
      () => ({
        empresarial: crearImporteMonetario("0.0075"),
        trabajador: crearImporteMonetario("0.0015"),
      })
    ),
    Match.orElse(() => ({
      empresarial: IMPORTE_CERO,
      trabajador: IMPORTE_CERO,
    }))
  )

export function reduccionRentasBajas2025(RN: Decimal): Decimal {
  return D.min(
    D.max(RN, 0),
    D.max(0, new D(1620).minus(D.max(0, RN.minus(8000)).times("0.405")))
  )
}

